INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21711, 'iron-oxide-hematite-2', 'published', 'Iron Oxide Hematite', 'coreloss', 'eels', 'counts', 'Fe2O3 (alpha)', 'natural sample, ouro preto mine, Brazil', 'The hematite O-K prepeak maxima have been set at 529.4 and 530.6 eV.' || char(13) || '' || char(10) || 'Energy resolution improved by Richardson-Lucy deconvolution Analyst: A. Gloter, A. Chen. Temperature: Room. ', 523.05, 554.0, 0.05, 'Alex Gloter', 'alexg', '2008-02-08 00:00:00', '2008-02-08 00:00:00', 'full', 121, '{"id":21711,"title":"Iron Oxide Hematite","permalink":"https://eelsdb.eu/spectra/iron-oxide-hematite-2/","author":{"name":"Alex Gloter","profile_url":"https://eelsdb.eu/author/alexg/","profile_api_url":"https://api.eelsdb.eu/author/alexg/"},"published":"2008-02-08 00:00:00","description":"The hematite O-K prepeak maxima have been set at 529.4 and 530.6 eV.\r\nEnergy resolution improved by Richardson-Lucy deconvolution Analyst: A. Gloter, A. Chen. Temperature: Room. ","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/iron-oxide-hematite-2/","keywords":["imported from old site"],"download_link":"https://eelsdb.eu/wp-content/uploads/2015/09/DspecVwCaEV.msa","type":"Core Loss","formula":"Fe2O3 (alpha)","elements":["Fe","O"],"microscope":"STEM-VG","max_energy":"554 eV","min_energy":"523.05 eV","source_purity":"natural sample, ouro preto mine, Brazil","edges":["O_K"],"guntype":"Cold FEG","beamenergy":"100 kV","monochromated":"No","stepSize":"0.05 eV/pixel","convergence":"7.5 mrad","collection":"24 mrad","detector":"Parallel: 666 Gatan","darkcurrent":"No","gainvariation":"No","other_links":[{"url":"http://pc-web.cemes.fr/eelsdb/index.php?page=displayspec.php&id=201","title":"Old EELS DB"}]}');
INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21668, 'hematite', 'published', 'Hematite', 'coreloss', 'eels', 'counts', 'Fe2O3 (alpha)', 'Powder bought from Alfa-aesar and checked with XRD', 'Spectrum has been processed in digitalmicrograph, background subtraction and fourier deconvolved.  Unprocessed data and associated low loss will be uploaded at a later date. Analyst: Ying-Hsi Pan. Temperature: 293. BEAM/Crystal: off-axis. ', 685.9, 788.2, 0.1, 'Andy Brown', 'a-p-brown', '2008-01-08 00:00:00', '2008-01-08 00:00:00', 'full', 122, '{"id":21668,"title":"Hematite","permalink":"https://eelsdb.eu/spectra/hematite/","author":{"name":"Andy Brown","profile_url":"https://eelsdb.eu/author/a-p-brown/","profile_api_url":"https://api.eelsdb.eu/author/a-p-brown/"},"published":"2008-01-08 00:00:00","description":"Spectrum has been processed in digitalmicrograph, background subtraction and fourier deconvolved.  Unprocessed data and associated low loss will be uploaded at a later date. Analyst: Ying-Hsi Pan. Temperature: 293. BEAM/Crystal: off-axis. ","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/hematite/","keywords":["imported from old site"],"download_link":"https://eelsdb.eu/wp-content/uploads/2015/09/DspecgxvQRC.msa","type":"Core Loss","formula":"Fe2O3 (alpha)","elements":["Fe","O"],"microscope":"Philips CM200","max_energy":"788.2 eV","min_energy":"685.9 eV","source_purity":"Powder bought from Alfa-aesar and checked with XRD","edges":["Fe_L2,3"],"guntype":"feg Schottky","beamenergy":"197 kV","resolution":"0.8 eV","stepSize":"0.1 eV/pixel","acquisition_mode":"Diffraction","convergence":"1 mrad","collection":"5.9 mrad","probesize":"180 nm^2","integratetime":"15 secs","readouts":"1","detector":"GIF: GIF200","darkcurrent":"Yes","gainvariation":"Yes","reference":{"freetext":"Pan et al., Micron vol 37, 2006"},"other_links":[{"url":"http://pc-web.cemes.fr/eelsdb/index.php?page=displayspec.php&id=157","title":"Old EELS DB"}]}');
