INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21709, 'iron-oxide-magnetite', 'published', 'Iron Oxide Magnetite', 'coreloss', 'eels', 'counts', 'Fe3O4', 'Natural sample (from magnetotactic bacteria)', 'The maximum L3 line of magnetite has been measured 0.4 eV lower in energy with respect to the L3 line maximum of hematite. Both samples deposited onto the same grid. ' || char(13) || '' || char(10) || 'We use the hematite as a Fe3+ reference, maximum of the L3 line set at 710.5 eV to match with some XAS previously reported work. see  Kuiper et al., Phys. Rev. Lett. 70, 1549 - 1552 (1993)' || char(13) || '' || char(10) || 'Energy resolution improved by Richardson-Lucy deconvolution Analyst: A. Gloter, A. Chen. Temperature: Room. ', 683.75, 729.25, 0.05, 'Alex Gloter', 'alexg', '2008-02-08 00:00:00', '2008-02-08 00:00:00', 'full', 126, '{"id":21709,"title":"Iron Oxide Magnetite","permalink":"https://eelsdb.eu/spectra/iron-oxide-magnetite/","author":{"name":"Alex Gloter","profile_url":"https://eelsdb.eu/author/alexg/","profile_api_url":"https://api.eelsdb.eu/author/alexg/"},"published":"2008-02-08 00:00:00","description":"The maximum L3 line of magnetite has been measured 0.4 eV lower in energy with respect to the L3 line maximum of hematite. Both samples deposited onto the same grid. \r\nWe use the hematite as a Fe3+ reference, maximum of the L3 line set at 710.5 eV to match with some XAS previously reported work. see  Kuiper et al., Phys. Rev. Lett. 70, 1549 - 1552 (1993)\r\nEnergy resolution improved by Richardson-Lucy deconvolution Analyst: A. Gloter, A. Chen. Temperature: Room. ","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/iron-oxide-magnetite/","keywords":["imported from old site"],"download_link":"https://eelsdb.eu/wp-content/uploads/2015/09/DspecJtJUhK.msa","type":"Core Loss","formula":"Fe3O4","elements":["Fe","O"],"microscope":"STEM-VG","max_energy":"729.25 eV","min_energy":"683.75 eV","source_purity":"Natural sample (from magnetotactic bacteria)","edges":["Fe_L2,3"],"guntype":"Cold FEG","beamenergy":"100 kV","monochromated":"No","stepSize":"0.05 eV/pixel","convergence":"7.5 mrad","collection":"24 mrad","detector":"Parallel: 666 Gatan","darkcurrent":"No","gainvariation":"No","other_links":[{"url":"http://pc-web.cemes.fr/eelsdb/index.php?page=displayspec.php&id=199","title":"Old EELS DB"}]}');
INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21715, 'iron-oxide-magnetite-2', 'published', 'Iron Oxide Magnetite', 'coreloss', 'eels', 'counts', 'Fe3O4', 'Natural sample (from magnetotactic bacteria)', 'The energy calibration have been done by measuring the EELS spectra of this phase with respect to the EELS spectra of an Hematite sample. The Hematite and magnetite samples beeing deposited onto the same grid. The hematite O-K prepeak maxima have been set at 529.4 and 530.6 eV.' || char(13) || '' || char(10) || '' || char(13) || '' || char(10) || 'Energy resolution improved by Richardson-Lucy deconvolution Analyst: A. Gloter, A. Chen. Temperature: Room. ', 524.45, 555.85, 0.05, 'Alex Gloter', 'alexg', '2008-02-08 00:00:00', '2008-02-08 00:00:00', 'full', 127, '{"id":21715,"title":"Iron Oxide Magnetite","permalink":"https://eelsdb.eu/spectra/iron-oxide-magnetite-2/","author":{"name":"Alex Gloter","profile_url":"https://eelsdb.eu/author/alexg/","profile_api_url":"https://api.eelsdb.eu/author/alexg/"},"published":"2008-02-08 00:00:00","description":"The energy calibration have been done by measuring the EELS spectra of this phase with respect to the EELS spectra of an Hematite sample. The Hematite and magnetite samples beeing deposited onto the same grid. The hematite O-K prepeak maxima have been set at 529.4 and 530.6 eV.\r\n\r\nEnergy resolution improved by Richardson-Lucy deconvolution Analyst: A. Gloter, A. Chen. Temperature: Room. ","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/iron-oxide-magnetite-2/","keywords":["imported from old site"],"download_link":"https://eelsdb.eu/wp-content/uploads/2015/09/DspecmpIe7P.msa","type":"Core Loss","formula":"Fe3O4","elements":["Fe","O"],"microscope":"STEM-VG","max_energy":"555.85 eV","min_energy":"524.45 eV","source_purity":"Natural sample (from magnetotactic bacteria)","edges":["O_K"],"guntype":"Cold FEG","beamenergy":"100 kV","monochromated":"No","stepSize":"0.05 eV/pixel","convergence":"7.5 mrad","collection":"24 mrad","detector":"Parallel: 666 Gatan","darkcurrent":"No","gainvariation":"No","other_links":[{"url":"http://pc-web.cemes.fr/eelsdb/index.php?page=displayspec.php&id=205","title":"Old EELS DB"}]}');
INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (22056, 'feal', 'published', 'FeAl', 'coreloss', 'eels', 'counts', 'FeAl', NULL, '', 612.0, 865.5, 0.25, 'magnunor', 'magnus', '2016-12-07 11:25:56', '2016-12-07 11:25:56', 'full', 128, '{"id":22056,"title":"FeAl","permalink":"https://eelsdb.eu/spectra/feal/","author":{"name":"magnunor","profile_url":"https://eelsdb.eu/author/magnus/","profile_api_url":"https://api.eelsdb.eu/author/magnus/"},"published":"2016-12-07 11:25:56","description":"","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/feal/","download_link":"https://eelsdb.eu/wp-content/uploads/2016/12/FeAl2.msa","type":"Core Loss","formula":"FeAl","elements":["Fe","Al"],"microscope":"ARM 200cF","max_energy":"865.5 eV","min_energy":"612 eV","edges":["Fe_L2,3"],"guntype":"Cold Field Emission Gun","beamenergy":"200 kV","resolution":"0.7 eV","monochromated":"No","stepSize":"0.25 eV/pixel","convergence":"27.42 mrad","collection":"33.19 mrad","detector":"GIF Quantum ER","darkcurrent":"No","gainvariation":"No","calibration":"Energy scale aligned using zero loss peak"}');
INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21710, 'iron-oxide-siderite', 'published', 'Iron Oxide Siderite', 'coreloss', 'eels', 'counts', 'FeCO3', 'Natural sample, strongly substituted (Fe0.79Mn0.12Mg0.07Ca0.02CO3)', 'The maximum L3 line of the iron divalent FeCO3 siderite has been measured 1.6 eV lower in energy with respect to the L3 line maximum of hematite. Both samples deposited onto the same grid. ' || char(13) || '' || char(10) || 'We use the hematite as a Fe3+ reference, maximum of the L3 line set at 710.5 eV to match with some XAS previously reported work. see  Kuiper et al., Phys. Rev. Lett. 70, 1549 - 1552 (1993)' || char(13) || '' || char(10) || 'Energy resolution improved by Richardson-Lucy deconvolution Analyst: A. Gloter, A. Chen. Temperature: Room. ', 690.75, 732.0, 0.05, 'Alex Gloter', 'alexg', '2008-02-08 00:00:00', '2008-02-08 00:00:00', 'full', 129, '{"id":21710,"title":"Iron Oxide Siderite","permalink":"https://eelsdb.eu/spectra/iron-oxide-siderite/","author":{"name":"Alex Gloter","profile_url":"https://eelsdb.eu/author/alexg/","profile_api_url":"https://api.eelsdb.eu/author/alexg/"},"published":"2008-02-08 00:00:00","description":"The maximum L3 line of the iron divalent FeCO3 siderite has been measured 1.6 eV lower in energy with respect to the L3 line maximum of hematite. Both samples deposited onto the same grid. \r\nWe use the hematite as a Fe3+ reference, maximum of the L3 line set at 710.5 eV to match with some XAS previously reported work. see  Kuiper et al., Phys. Rev. Lett. 70, 1549 - 1552 (1993)\r\nEnergy resolution improved by Richardson-Lucy deconvolution Analyst: A. Gloter, A. Chen. Temperature: Room. ","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/iron-oxide-siderite/","keywords":["imported from old s