INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21731, 'helium', 'published', 'Helium', 'coreloss', 'eels', 'counts', 'He', '19.5 nm Helium bubble in an aged tritiated Pd90Pt10 matrix', 'He K line (1s -> 2p) from a pressured He bubble formed in a tritiated PdPt matrix.' || char(13) || '' || char(10) || 'The energy of the K line depends on the pressure (here 22 eV at 0.1 Gpa) . It has to be compared to the value for an isolated atom: 21.218 eV.' || char(13) || '' || char(10) || 'The 1s->3p transition is also visible in the spectrum at 23.8 eV' || char(13) || '' || char(10) || 'See paper for details Analyst: Odile Stephan,Dario Taverna. Temperature: Room. ', 14.98, 32.93, 0.048, 'Odile Stephan', 'stephan', '2008-02-25 00:00:00', '2008-02-25 00:00:00', 'full', 151, '{"id":21731,"title":"Helium","permalink":"https://eelsdb.eu/spectra/helium/","author":{"name":"Odile Stephan","profile_url":"https://eelsdb.eu/author/stephan/","profile_api_url":"https://api.eelsdb.eu/author/stephan/"},"published":"2008-02-25 00:00:00","description":"He K line (1s -> 2p) from a pressured He bubble formed in a tritiated PdPt matrix.\r\nThe energy of the K line depends on the pressure (here 22 eV at 0.1 Gpa) . It has to be compared to the value for an isolated atom: 21.218 eV.\r\nThe 1s->3p transition is also visible in the spectrum at 23.8 eV\r\nSee paper for details Analyst: Odile Stephan,Dario Taverna. Temperature: Room. ","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/helium/","keywords":["imported from old site"],"download_link":"https://eelsdb.eu/wp-content/uploads/2015/09/Dspecc0KOZx.msa","type":"Core Loss","formula":"He","elements":["He"],"microscope":"STEM-VG","max_energy":"32.93 eV","min_energy":"14.98 eV","source_purity":"19.5 nm Helium bubble in an aged tritiated Pd90Pt10 matrix","edges":["He_K"],"guntype":"Cold FEG","beamenergy":"100 kV","resolution":"0.7 eV","stepSize":"0.048 eV/pixel","acquisition_mode":"STEM","convergence":"15 mrad","collection":"24 mrad","probesize":"1 nm^2","integratetime":"0.2 secs","readouts":"50","detector":"Parallel: 666 Gatan","darkcurrent":"Yes","gainvariation":"No","reference":{"freetext":"S. Taverna, M. Kocia, O.Stephan et al., PRL, 100, 035301, 2008"},"other_links":[{"url":"http://pc-web.cemes.fr/eelsdb/index.php?page=displayspec.php&id=221","title":"Old EELS DB"}]}');
INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (22105, 'hosse-tas2se-misfit-nanotube', 'published', 'HoS(Se)-TaS2(Se) misfit nanotube', 'coreloss', 'eels', 'counts', 'HoS(Se)-TaS2(Se)', NULL, '', 1124.8, 2635.48, 0.738, 'Luc Lajaunie', 'luc-lajaunie', '2018-01-15 12:57:04', '2018-01-15 12:57:04', 'full', 152, '{"id":22105,"title":"HoS(Se)-TaS2(Se) misfit nanotube","permalink":"https://eelsdb.eu/spectra/hosse-tas2se-misfit-nanotube/","author":{"name":"Luc Lajaunie","profile_url":"https://eelsdb.eu/author/luc-lajaunie/","profile_api_url":"https://api.eelsdb.eu/author/luc-lajaunie/"},"published":"2018-01-15 12:57:04","description":"","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/hosse-tas2se-misfit-nanotube/","download_link":"https://eelsdb.eu/wp-content/uploads/2018/01/cvert.msa","type":"Core Loss","formula":"HoS(Se)-TaS2(Se)","elements":["Ho","S","Se","Ta"],"microscope":"FEI Titan Low-Base","max_energy":"2635.48 eV","min_energy":"1124.8 eV","edges":["S_K","Se_L1","Se_L2,3","Ta_M4,5","Ho_M4,5"],"guntype":"X-FEG","beamenergy":"200 kV","resolution":"2 eV","monochromated":"No","stepSize":"0.738 eV/pixel","convergence":"18 mrad","collection":"25 mrad","detector":"Gatan Tridiem ESR 865","darkcurrent":"No","gainvariation":"No","calibration":"low loss + drift tube","reference":{"authors":"Luc Lajaunie, Gal Radovsky, Reshef Tenne, Raul Arenal","year":"2017","journal":"Inorganic Chemistry","title":"Quaternary Chalcogenide-Based Misfit Nanotubes LnS(Se)-TaS(Se)2 (Ln = La, Ce, Nd, and Ho): Synthesis and Atomic Structural Studies","doi":"10.1021/acs.inorgchem.7b02680","url":"http://dx.doi.org/10.1021/acs.inorgchem.7b02680"}}');
INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21913, 'la0-7sr0-3mno3srtio3-001-heterostructure', 'published', 'La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure', 'coreloss', 'eels', 'counts', 'La0.7Sr0.3MnO3', NULL, '35 nm La0.7Sr0.3MnO3 thin film grown epitaxially on a SrTiO3 substrate using PLD, acquired from the middle of film.', 628.4, 682.4, 0.2, 'magnunor', 'magnus', '2016-02-10 14:28:23', '2016-02-10 14:28:23', 'full', 153, '{"id":21913,"title":"La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure","permalink":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure/","author":{"name":"magnunor","profile_url":"https://eelsdb.eu/author/magnus/","profile_api_url":"https://api.eelsdb.eu/author/magnus/"},"published":"2016-02-10 14:28:23","description":"35 nm La0.7Sr0.3MnO3 thin film grown epitaxially on a SrTiO3 substrate using PLD, acquired from the middle of film.","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure/","download_link":"https://eelsdb.eu/wp-content/uploads/2016/02/lsmo_mn2.msa","type":"Core Loss","formula":"La0.7Sr0.3MnO3","elements":["La","Sr","Mn","O"],"microscope":"FEI Titan 80-300ST","max_energy":"682.4 eV","min_energy":"628.4 eV","edges":["Mn_L2,3"],"guntype":"Field Emission Gun","beamenergy":"300 kV","resolution":"1.0 eV","monochromated":"No","stepSize":"0.2 eV/pixel","convergence":"24.2 mrad","collection":"33.1 mrad","detector":"GIF","darkcurrent":"No","gainvariation":"No","calibration":"zero + dispersion","reference":{"authors":"M. Nord, P. E. Vullum, M. Moreau, J. E. Boschker, S. M. Selbach, R. Holmestad, T. Tybell","year":"2015","journal":"Appl. Phys. Lett.","title":"Structural phases driven by oxygen vacancies at the La0.7Sr0.3MnO3/SrTiO3 hetero-interface","volume":"106","issue":"4","page":"041604","doi":"10.1063/1.4906920","url":"http://dx.doi.org/10.1063/1.4906920"},"associated_spectra":[{"name":"La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure, oxygen vacancies","link":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-oxygen-vacancies/","type":"Core Loss"},{"name":"La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure, brown millerite oxygen vacancies","link":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-brown-millerite-oxygen-vacancies/","type":"Core Loss"},{"name":"La0.7Sr0.3MnO3/SrTiO3-(001) Heterostructure","link":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-2/","type":"Core Loss"}]}');
INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21915, 'la0-7sr0-3mno3srtio3-001-heterostructure-oxygen-vacancies', 'published', 'La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure, oxygen vacancies', 'coreloss', 'eels', 'counts', 'La0.7Sr0.3MnO3', NULL, '35 nm La0.7Sr0.3MnO3 thin film grown epitaxially on a SrTiO3 substrate using PLD. Acquired at the LSMO/STO interface, had a reduced amount of oxygen content in relation to the middle of the film.', 628.4, 682.4, 0.2, 'magnunor', 'magnus', '2016-02-10 14:26:55', '2016-02-10 14:26:55', 'full', 154, '{"id":21915,"title":"La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure, oxygen vacancies","permalink":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-oxygen-vacancies/","author":{"name":"magnunor","profile_url":"https://eelsdb.eu/author/magnus/","profile_api_url":"https://api.eelsdb.eu/author/magnus/"},"published":"2016-02-10 14:26:55","description":"35 nm La0.7Sr0.3MnO3 thin film grown epitaxially on a SrTiO3 substrate using PLD. Acquired at the LSMO/STO interface, had a reduced amount of oxygen content in relation to the middle of the film.","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-oxygen-vacancies/","download_link":"https://eelsdb.eu/wp-content/uploads/2016/02/lsmo_mn_interface_oxygen_vacancies2.msa","type":"Core Loss","formula":"La0.7Sr0.3MnO3","elements":["La","Sr","Mn","O"],"microscope":"FEI Titan 80-300ST","max_energy":"682.4 eV","min_energy":"628.4 eV","edges":["Mn_L2,3"],"guntype":"Field Emission Gun","beamenergy":"300 kV","resolution":"1.0 eV","monochromated":"No","stepSize":"0.2 eV/pixel","convergence":"24.2 mrad","collection":"33.1 mrad","detector":"GIF","darkcurrent":"No","gainvariation":"No","calibration":"zero + dispersion","reference":{"authors":"M. Nord, P. E. Vullum, M. Moreau, J. E. Boschker, S. M. Selbach, R. Holmestad, T. Tybell","year":"2015","journal":"Appl. Phys. Lett.","title":"Structural phases driven by oxygen vacancies at the La0.7Sr0.3MnO3/SrTiO3 hetero-interface","volume":"106","issue":"4","page":"041604","doi":"10.1063/1.4906920","url":"http://dx.doi.org/10.1063/1.4906920"},"associated_spectra":[{"name":"La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure","link":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure/","type":"Core Loss"},{"name":"La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure, brown millerite oxygen vacancies","link":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-brown-millerite-oxygen-vacancies/","type":"Core Loss"},{"name":"La0.7Sr0.3MnO3/SrTiO3-(001) Heterostructure, Oxygen Vacancies","link":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-oxygen-vacancies-2/","type":"Core Loss"}]}');
INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21917, 'la0-7sr0-3mno3srtio3-001-heterostructure-brown-millerite-oxygen-vacancies', 'published', 'La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure, brown millerite oxygen vacancies', 'coreloss', 'eels', 'counts', 'La0.7Sr0.3MnO3', NULL, '35 nm La0.7Sr0.3MnO3 thin film grown on SrTiO3-(001) using PLD. After 1.5 years, brownmillerite structure (La0.7Sr0.3MnO2.5) had formed in the thin film.', 644.7, 682.8, 0.1, 'magnunor', 'magnus', '2016-02-10 14:24:51', '2016-02-10 14:24:51', 'full', 155, '{"id":21917,"title":"La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure, brown millerite oxygen vacancies","permalink":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-brown-millerite-oxygen-vacancies/","author":{"name":"magnunor","profile_url":"https://eelsdb.eu/author/magnus/","profile_api_url":"https://api.eelsdb.eu/author/magnus/"},"published":"2016-02-10 14:24:51","description":"35 nm La0.7Sr0.3MnO3 thin film grown on SrTiO3-(001) using PLD. After 1.5 years, brownmillerite structure (La0.7Sr0.3MnO2.5) had formed in the thin film.","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-brown-millerite-oxygen-vacancies/","download_link":"https://eelsdb.eu/wp-content/uploads/2016/02/lsmo_mn_brownmillerite2.msa","type":"Core Loss","formula":"La0.7Sr0.3MnO3","elements":["La","Sr","Mn","O"],"microscope":"ARM 200cF","max_energy":"682.8 eV","min_energy":"644.7 eV","edges":["Mn_L2,3"],"guntype":"Cold Field Emission Gun","beamenergy":"200 kV","resolution":"0.7 eV","monochromated":"No","stepSize":"0.1 eV/pixel","acquisition_mode":"stem","convergence":"27.42 mrad","collection":"66.89 mrad","detector":"GIF Quantum ER","darkcurrent":"No","gainvariation":"No","calibration":"Zero loss","reference":{"authors":"M. Nord, P. E. Vullum, M. Moreau, J. E. Boschker, S. M. Selbach, R. Holmestad, T. Tybell","year":"2015","journal":"Appl. Phys. Lett.","title":"Structural phases driven by oxygen vacancies at the La0.7Sr0.3MnO3/SrTiO3 hetero-interface","volume":"106","issue":"4","page":"041604","doi":"10.1063/1.4906920","url":"http://dx.doi.org/10.1063/1.4906920"},"associated_spectra":[{"name":"La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure","link":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure/","type":"Core Loss"},{"name":"La0.7Sr0.3MnO3/SrTiO3-(001) heterostructure, oxygen vacancies","link":"https://eelsdb.eu/spectra/la0-7sr0-3mno3srtio3-001-heterostructure-oxygen-vacancies/","type":"Core Loss"}]}');
