INSERT INTO spectra (id, slug, status, title, type, technique, intensity_units, formula, source_purity, description, min_energy_ev, max_energy_ev, step_ev, author_display, author_slug, published_at, created_at, completeness, legacy_rank, legacy_v1) VALUES (21602, '99-99-nickel-metal', 'published', '99.99% Nickel metal', 'coreloss', 'eels', 'counts', 'Ni', NULL, 'The background was model as a power law using a window of 10 eV width. ' || char(13) || '' || char(10) || 'The spectrum was deconvoluted by the Fourier-ratio method using low-loss spectra collected from the same region and under similar conditions except for a reduced illumination intensity. Analyst: P. Potapov. Temperature: Room. BEAM/Crystal: close to [101] zone axis. ', 846.5, 897.15, 0.05, '(Dr) Marie Cheynet', 'mcheynet', '2005-05-26 00:00:00', '2005-05-26 00:00:00', 'full', 199, '{"id":21602,"title":"99.99% Nickel metal","permalink":"https://eelsdb.eu/spectra/99-99-nickel-metal/","author":{"name":"(Dr) Marie Cheynet","profile_url":"https://eelsdb.eu/author/mcheynet/","profile_api_url":"https://api.eelsdb.eu/author/mcheynet/"},"published":"2005-05-26 00:00:00","description":"The background was model as a power law using a window of 10 eV width. \r\nThe spectrum was deconvoluted by the Fourier-ratio method using low-loss spectra collected from the same region and under similar conditions except for a reduced illumination intensity. Analyst: P. Potapov. Temperature: Room. BEAM/Crystal: close to [101] zone axis. ","comment_count":0,"api_permalink":"https://api.eelsdb.eu/spectra/99-99-nickel-metal/","keywords":["imported from old site"],"download_link":"https://eelsdb.eu/wp-content/uploads/2015/09/DspecJ0t8eT.msa","type":"Core Loss","formula":"Ni","elements":["Ni"],"microscope":"CM30","max_energy":"897.15 eV","min_energy":"846.5 eV","edges":["Ni_L2,3"],"guntype":"feg Schottky","beamenergy":"300 kV","resolution":"1.1 eV","stepSize":"0.05 eV/pixel","acquisition_mode":"Diffraction","convergence":"0.5 mrad","collection":"3.5 mrad","probesize":"500 nm^2","integratetime":"10 secs","readouts":"10","detector":"Parallel: GIF","darkcurrent":"Yes","gainvariation":"Yes","thickness":"0.5 t/&lambda;","reference":{"freetext":"Structural and chemical effects on EELS L2,3 ionisation edges in Ni-based intermetallic compounds\r\nP.L. Potapov, S.E. Kulkova, D. Schryvers, J. Verbeeck\r\nPhys. Rev. B 64, 184110 (2001)"},"other_links":[{"url":"http://pc-web.cemes.fr/eelsdb/index.php?page=displayspec.php&id=85","title":"Old EELS DB"}]}');
